# name -> (recognition site, cut offset after which the cut occurs)
ENZYMES = {
    "EcoRI": ("GAATTC", 1),   # G^AATTC
    "BamHI": ("GGATCC", 1),   # G^GATCC
    "HindIII": ("AAGCTT", 1), # A^AGCTT
}


def find_cuts(seq, enzymes, circular=False):
    """Return sorted list of cut positions (0-based, position = index after
    which the backbone is nicked) for the given enzymes."""
    cuts = []
    n = len(seq)
    for enz in enzymes:
        site, offset = ENZYMES[enz]
        positions = range(n) if circular else range(n - len(site) + 1)
        for i in positions:
            candidate = seq[i:i + len(site)]
            if circular and i + len(site) > n:
                candidate = seq[i:] + seq[:i + len(site) - n]
            if candidate == site:
                cuts.append((i + offset) % n)
    return sorted(set(cuts))


def digest(seq, enzymes, circular=False):
    """Return (cut_positions, fragment_lengths)."""
    n = len(seq)
    cuts = find_cuts(seq, enzymes, circular)

    if not cuts:
        return [], [n] if not circular else []

    fragments = []
    if not circular:
        prev = 0
        for c in cuts:
            fragments.append(c - prev)
            prev = c
        fragments.append(n - prev)
    else:
        prev = cuts[-1] - n
        for c in cuts:
            fragments.append(c - prev)
            prev = c

    return cuts, fragments
